#!/usr/bin/env python3
"""Build FAKE fixture data and run promptfoo end-to-end OFFLINE (EVAL_MOCK=1).

Everything produced here is clearly fake (URLs on the reserved .invalid TLD, text
containing FIXTURE) and lives under tests/fixtures/ or out/fixture_charts/.
It proves the wiring: promptfoo -> python providers -> python assertions ->
JSON export -> analysis/analyze.py --fixture -> charts.

  .venv/bin/python tests/fixtures/make_fixtures.py [--no-run]
"""
from __future__ import annotations

import argparse
import csv
import json
import os
import random
import subprocess
import sys
from pathlib import Path

import yaml

FX = Path(__file__).resolve().parent
EVAL = FX.parents[1]
sys.path.insert(0, str(EVAL))
sys.path.insert(0, str(EVAL / "config"))
from lib.mock import qhash  # noqa: E402

import make_configs as mc  # noqa: E402

PROVIDERS = ["youcom", "tavily", "exa", "parallel", "firecrawl", "linkup"]


def keys_and_gt():
    rng = random.Random(7)
    rows = list(csv.DictReader(open(EVAL / "answer_keys.csv")))
    for r in rows:
        r["expected_answer"] = "FIXTURE ANSWER (fake key)"
        if r["expect_none"].startswith("[FILL"):
            r["expect_none"] = "true" if rng.random() < 0.4 else "false"
        r["notes"] = "FIXTURE - fake key for offline tests"
    with open(FX / "fixture_answer_keys.csv", "w", newline="") as f:
        w = csv.DictWriter(f, fieldnames=list(rows[0].keys()))
        w.writeheader()
        w.writerows(rows)
    gt = FX / "ground_truth"
    gt.mkdir(exist_ok=True)
    for uc in ("gtm", "insurance", "finance"):
        for t in yaml.safe_load(open(EVAL / "tests" / f"{uc}.yaml")):
            v = t["vars"]
            if v["answer_type"] != "list":
                continue
            h = qhash(v["query"])
            items = [{"url": f"https://fixture.invalid/{p}/{h}/{i}", "title": "FIXTURE gold item", "date": None}
                     for p in rng.sample(PROVIDERS, 3) for i in rng.sample(range(10), 2)]
            items += [{"url": f"https://fixture.invalid/missed/{h}/{i}", "title": "FIXTURE gold item nobody found", "date": None}
                      for i in range(2)]
            (gt / f"{v['qid']}.json").write_text(json.dumps({"qid": v["qid"], "FIXTURE": True, "items": items}, indent=1))


def friction():
    rng = random.Random(11)
    from friction.log import COLUMNS
    cats = ["signup", "auth", "docs", "params", "rate limit", "latency", "billing/credits", "results quality"]
    with open(FX / "fixture_friction_log.csv", "w", newline="") as f:
        w = csv.DictWriter(f, fieldnames=COLUMNS)
        w.writeheader()
        for p in PROVIDERS:
            for _ in range(rng.randint(1, 6)):
                w.writerow({"time_utc": "2026-01-01T00:00:00Z", "provider": p, "category": rng.choice(cats),
                            "step": "FIXTURE step", "actual": "FIXTURE fake friction row", "severity": rng.choice(["Green", "Yellow", "Red"]),
                            "source": rng.choice(["manual", "auto"]), "qid": "", "run_id": "fixture", "raw_file": ""})
    with open(FX / "fixture_friction_summary.csv", "w", newline="") as f:
        w = csv.writer(f)
        w.writerow(["provider", "signup_start_utc", "first_success_utc", "ttfc_minutes", "signup_steps", "card_required",
                    "free_credits", "credits_visible_in_api", "docs_pages_before_first_call", "errors_before_success",
                    "red", "yellow", "green", "biggest_issue"])
        for p in PROVIDERS:
            w.writerow([p, "", "", rng.randint(3, 40), rng.randint(2, 6), rng.choice(["yes", "no"]), "FIXTURE", "", rng.randint(1, 5),
                        rng.randint(0, 3), 0, 1, 2, "FIXTURE issue"])


def configs():
    rel = lambda s: s.replace("file://", "file://../../") if isinstance(s, str) and s.startswith("file://") else s
    for uc in ("gtm", "insurance", "finance"):
        cfg = mc.config(uc, f"file://../{uc}.yaml", mode="offline")
        cfg["description"] = f"FIXTURE (offline mock) - {uc}"
        cfg["prompts"] = [rel(p) for p in cfg["prompts"]]
        for p in cfg["providers"]:
            p["id"] = rel(p["id"])
            p["config"]["pythonExecutable"] = str(EVAL / ".venv" / "bin" / "python")
        cfg["defaultTest"]["assert"] = [dict(a, value=rel(a.get("value"))) if a.get("value") else a
                                        for a in cfg["defaultTest"]["assert"] if a["type"] != "context-faithfulness"]
        cfg.pop("outputPath", None)
        cfg["evaluateOptions"] = {"maxConcurrency": 8}
        (FX / f"promptfooconfig.fixture.{uc}.yaml").write_text("# FIXTURE / offline mock config - generated by make_fixtures.py\n"
                                                               + yaml.safe_dump(cfg, sort_keys=False, width=200))
    # per-test asserts in tests/*.yaml use file://asserts/... relative to the TEST file's config dir;
    # promptfoo resolves them relative to the config file, so the fixture configs load copies with fixed paths
    for uc in ("gtm", "insurance", "finance"):
        tests = yaml.safe_load(open(EVAL / "tests" / f"{uc}.yaml"))
        for t in tests:
            t["assert"] = [dict(a, value=rel(a["value"])) for a in t.get("assert", [])]
        (FX / f"fixture_tests_{uc}.yaml").write_text(yaml.safe_dump(tests, sort_keys=False, width=200))
        c = (FX / f"promptfooconfig.fixture.{uc}.yaml").read_text().replace(f"file://../{uc}.yaml", f"file://fixture_tests_{uc}.yaml")
        (FX / f"promptfooconfig.fixture.{uc}.yaml").write_text(c)


def grades():
    """FAKE Claude Code grades for the fixture exports -> tests/fixtures/grades/grades_{uc}.csv."""
    sys.path.insert(0, str(EVAL / "grading"))
    sys.path.insert(0, str(EVAL / "analysis"))
    import export
    from pf_load import load
    from lib.keys import load_keys
    keys = load_keys(FX / "fixture_answer_keys.csv")
    skill = {"youcom": 0.7, "tavily": 0.62, "exa": 0.6, "parallel": 0.66, "firecrawl": 0.5, "linkup": 0.55}
    (FX / "grades").mkdir(exist_ok=True)
    for uc in ("gtm", "insurance", "finance"):
        rng = random.Random(f"grades-{uc}")
        lines = export.build(load(FX / f"fixture_{uc}_results.json")["rows"], keys)
        with open(FX / "grades" / f"grades_{uc}.csv", "w", newline="") as f:
            w = csv.DictWriter(f, fieldnames=export.GRADE_COLUMNS)
            w.writeheader()
            for ln in lines:
                n = len(ln["results"])
                rel = [int(rng.random() < skill[ln["provider"]]) if i < n else 0 for i in range(5)]
                lab = rng.choices(["CORRECT", "INCORRECT", "NOT_ATTEMPTED"], [skill[ln["provider"]], 0.25, 0.1])[0]
                acc = 2 if lab == "CORRECT" else (1 if ln["answer_type"] == "list" and rng.random() < 0.5 else 0)
                cited = [f"r{i + 1}" for i in range(n) if rel[i]][:2]
                w.writerow({"qid": ln["qid"], "provider": ln["provider"], "answer_text": "FIXTURE answer (fake grade)",
                            "accuracy_0_2": acc if n else 0, "simpleqa_label": lab if n else "NOT_ATTEMPTED",
                            "correct_none": "" if ln["expect_none"] is None else int(rng.random() < 0.7),
                            **{f"rel_r{i + 1}": rel[i] for i in range(5)}, "precision_at_5": sum(rel) / 5,
                            "cited_result_ids": ";".join(cited), "citation_supported": int(rng.random() < 0.8) if cited else "",
                            "grader": "claude-code", "human_check": "", "notes": "FIXTURE - fake grade"})


def run():
    env = dict(os.environ, EVAL_MOCK="1", EVAL_KEYS_CSV=str(FX / "fixture_answer_keys.csv"),
               EVAL_GT_DIR=str(FX / "ground_truth"), EVAL_NO_FRICTION_AUTOLOG="1", EVAL_MOCK_LATENCY_SCALE="0.3",
               PROMPTFOO_PYTHON=str(EVAL / ".venv" / "bin" / "python"), PROMPTFOO_DISABLE_TELEMETRY="1",
               EVAL_OUT_DIR=str(EVAL / "out" / "fixture_run"))
    for uc in ("gtm", "insurance", "finance"):
        out = FX / f"fixture_{uc}_results.json"
        cmd = ["npx", "promptfoo", "eval", "-c", str(FX / f"promptfooconfig.fixture.{uc}.yaml"), "--repeat", "3",
               "--no-cache", "--no-table", "-o", str(out)]
        print("$", " ".join(cmd))
        r = subprocess.run(cmd, cwd=EVAL, env=env)
        print(f"  exit {r.returncode} -> {out}")


if __name__ == "__main__":
    ap = argparse.ArgumentParser()
    ap.add_argument("--no-run", action="store_true")
    a = ap.parse_args()
    keys_and_gt()
    friction()
    configs()
    if not a.no_run:
        run()
    grades()
